let S;
const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);
let BG = "#000008";
let circles = [];

function setup() {
  createCanvas(S = 400, S);
	S /= 2;
	describe("circles packing on bottom with lineart gradient from  a color top to darkblue bottom")
  frameRate(30);
  noStroke();
  background(BG);
}

function draw() {
	if (frameCount > 100000) // noLoop() removed for animation
	if (S > 1) {
		while (!addCircle()) {}
	}

  push();
	blendMode(BLEND)
  stroke(0);
  fill(255);
  text("#minacoding 24/06 Morning", 0, 10);
  pop();
}

function addCircle() {
	const y = height - abs(height - randomGaussian(height, 75)); // force y to be high
	const x = randomGaussian(width/2, 100);
	const r = random(S/2, S/4) * (y / height); // force radius to be smaller in the top
	const c = random(CLRS);
	const circ = {x, y, r};
	if (!detectCollision(circ, circles)) {
		circles.push(circ);
		fill(c);
		ctxLinGrad(x, y-r, x, y+r, c, color(BG))
		circle(x, y, r+r);
		S -= 0.05;
		return true;
	}
	S -= 0.001;
	return false;
}

function detectCollision(circ, circles) {
	for (let c of circles) {
		if (dist(c.x, c.y, circ.x, circ.y) < c.r + circ.r) return true;
	}
	return false;
}

// linear gradient
function ctxLinGrad(x0, y0, x1, y1, c1, c2) {
	const ctx = this.drawingContext;
	const gradient = ctx.createLinearGradient(x0, y0, x1, y1);
	gradient.addColorStop(0, c1);
	gradient.addColorStop(1, c2);
	ctx.fillStyle = gradient;
	ctx.strokeStyle = gradient;
};
